const { itemTypeName,getState } = options;
const state = getState();
const visible = state.grid.selectedRows.some((itemId) => {
	const isEditableItem = state.editableItems.has(itemId);
	const isNewItem = ArasModules.item.isNew(itemTypeName, itemId);
	return isEditableItem && !isNewItem;
});

return { hidden: !visible };
